[{"order":1,"type":"heading","text":"Tutorial: Test Coverage and Code Quality with JUnit, JaCoCo, and SonarQube"},{"order":2,"type":"subheading","text":"Introduction"},{"order":3,"type":"paragraph","text":"Maintaining high code quality and test coverage is critical for enterprise software development. This tutorial demonstrates how to integrate JUnit for unit testing, JaCoCo for measuring code coverage, and SonarQube for continuous inspection of code quality."},{"order":4,"type":"subheading","text":"Prerequisites and Setup"},{"order":5,"type":"bullet_point","text":"Java Development Kit (JDK 11 or higher installed)"},{"order":6,"type":"bullet_point","text":"Apache Maven or Gradle build tool"},{"order":7,"type":"bullet_point","text":"JUnit 5 for writing unit tests"},{"order":8,"type":"bullet_point","text":"JaCoCo Maven Plugin configured in your pom.xml"},{"order":9,"type":"subheading","text":"Step 1: Configuring JaCoCo in Maven"},{"order":10,"type":"paragraph","text":"To collect test coverage data during the Maven test phase, add the JaCoCo plugin to the build section of your pom.xml file as shown below."},{"order":11,"type":"code","text":"<build>
    <plugins>
        <plugin>
            <groupId>org.jacoco</groupId>
            <artifactId>jacoco-maven-plugin</artifactId>
            <version>0.8.8</version>
            <executions>
                <execution>
                    <goals>
                        <goal>prepare-agent</goal>
                    </goals>
                </execution>
                <execution>
                    <id>report</id>
                    <phase>test</phase>
                    <goals>
                        <goal>report</goal>
                    </goals>
                </execution>
            </executions>
        </plugin>
    </plugins>
</build>"},{"order":12,"type":"subheading","text":"Step 2: Writing a Sample JUnit 5 Test"},{"order":13,"type":"paragraph","text":"Create a simple calculator class and a corresponding JUnit 5 test class to ensure our code has measurable paths for JaCoCo."},{"order":14,"type":"code","text":"public class Calculator {
    public int add(int a, int b) {
        return a + b;
    }
}"},{"order":15,"type":"code","text":"import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;

public class CalculatorTest {
    @Test
    public void testAdd() {
        Calculator calc = new Calculator();
        assertEquals(5, calc.add(2, 3));
    }
}"},{"order":16,"type":"subheading","text":"Step 3: Running Tests and Generating Coverage Reports"},{"order":17,"type":"paragraph","text":"Execute the following Maven command to compile the code, run the JUnit tests, and generate the JaCoCo coverage report:"},{"order":18,"type":"code","text":"mvn clean test"},{"order":19,"type":"paragraph","text":"Once executed, the HTML report will be available at target/site/jacoco/index.html."},{"order":20,"type":"subheading","text":"Step 4: Integrating with SonarQube"},{"order":21,"type":"paragraph","text":"To send code metrics and coverage data to SonarQube, run the SonarQube Maven goal. Ensure you have a local or remote SonarQube server running and provide the necessary authentication token."},{"order":22,"type":"code","text":"mvn sonar:sonar -Dsonar.projectKey=my-junit-project -Dsonar.host.url=http://localhost:9000 -Dsonar.login=your_sonar_token_here"},{"order":23,"type":"subheading","text":"Conclusion"},{"order":24,"type":"paragraph","text":"By combining JUnit, JaCoCo, and SonarQube, you establish a robust feedback loop that enforces code quality gates, tracks line and branch coverage, and prevents technical debt accumulation in your Java applications."}]
